#include <SFML/Graphics.hpp>
#include <deque>
#include <random>

#ifdef _WIN32
#include <windows.h>
#endif

#include "../include/world/lane.h"
#include "../include/utils/constants.h"

// ─────────────────────────────────────────────────────────────────────────────
//  TWEAK ME
//  How fast the whole map slides down the screen (pixels per second along +Oy).
//  Bigger = faster scroll. This is the one knob the brief asked to keep handy.
// ─────────────────────────────────────────────────────────────────────────────
static const float SCROLL_SPEED = 70.f;

// Number of lanes generated by generateMap() at start-up.
static const int NUM_LANES = 10;

// ── RNG helpers ──────────────────────────────────────────────────────────────

static std::mt19937 g_rng{std::random_device{}()};

static int randInt(int lo, int hi)
{
	std::uniform_int_distribution<int> dist(lo, hi);
	return dist(g_rng);
}

static Constants::LaneType randomLaneType()
{
	return (randInt(0, 1) == 0) ? Constants::LaneType::Grass
	                             : Constants::LaneType::Road;
}

static int randomDirection() { return (randInt(0, 1) == 0) ? 1 : -1; }
static int randomLevel()     { return randInt(1, 3); }

// ── Map generation ───────────────────────────────────────────────────────────

// Generate the initial 10 lanes, stacked top-to-bottom to exactly fill the
// window. Lane index i sits at y = i * LANE_HEIGHT. Each Lane seeds its own
// objects/traffic in its constructor, so the map is alive immediately.
static void generateMap(std::deque<Lane*>& lanes)
{
	for (int i = 0; i < NUM_LANES; ++i)
	{
		float y = static_cast<float>(i) * Constants::LANE_HEIGHT;
		lanes.push_back(new Lane({0.f, y}, randomLevel(),
		                         randomDirection(), randomLaneType()));
	}
}

// Make a lane to cover a new strip at the top of the screen.
// To avoid churning the heap we recycle a lane that has fully scrolled off the
// bottom (via Lane::spawnLane); only when none is available yet do we allocate.
// `lanes` stays sorted front (smallest y / top) → back (largest y / bottom).
static void spawnLane(std::deque<Lane*>& lanes, float new_y)
{
	Lane* lane;
	if (lanes.back()->getPosition().y >= static_cast<float>(Constants::WINDOW_HEIGHT))
	{
		lane = lanes.back();
		lanes.pop_back();
		lane->spawnLane({0.f, new_y}, randomLevel(), randomDirection());
	}
	else
	{
		lane = new Lane({0.f, new_y}, randomLevel(),
		                randomDirection(), randomLaneType());
	}
	lanes.push_front(lane);
}

// ── Sidebar (cosmetic) ───────────────────────────────────────────────────────

static void drawSidebar(sf::RenderWindow& window)
{
	sf::RectangleShape bar(
		{static_cast<float>(Constants::GAME_PLAY_BAR_WIDTH),
		 static_cast<float>(Constants::GAME_PLAY_BAR_HEIGHT)});
	bar.setFillColor({14, 14, 20});
	bar.setPosition({0.f, 0.f});
	window.draw(bar);
}

// ── Main ─────────────────────────────────────────────────────────────────────

int main()
{
#ifdef _WIN32
	SetProcessDPIAware();
#endif

	sf::RenderWindow window(
		sf::VideoMode({Constants::WINDOW_WIDTH, Constants::WINDOW_HEIGHT}),
		Constants::GAME_TITLE,
		sf::Style::Titlebar | sf::Style::Close);
	window.setFramerateLimit(60);

	std::deque<Lane*> lanes;
	generateMap(lanes);

	sf::Clock clock;

	while (window.isOpen())
	{
		// ── Events ───────────────────────────────────────────────────────────
		while (auto ev = window.pollEvent())
		{
			if (ev->is<sf::Event::Closed>())
				window.close();
			if (const auto* k = ev->getIf<sf::Event::KeyPressed>())
				if (k->code == sf::Keyboard::Key::Escape)
					window.close();
		}

		float dt = clock.restart().asSeconds();
		if (dt > 0.05f) dt = 0.05f; // clamp big hitches (e.g. window drag)

		// ── Update ─────────────────────────────────────────────────────────
		// 1) Slide every lane down by SCROLL_SPEED, then update it. Objects
		//    re-derive their y from the lane inside updateState(), so they
		//    follow the scroll automatically (Vehicle/Animal/Traffic all do).
		//    setPosition() is the public mover (it also pins x to the lane
		//    column); moveBy() is protected.
		for (Lane* lane : lanes)
		{
			lane->setPosition({0.f, lane->getPosition().y + SCROLL_SPEED * dt});
			lane->updateState(dt);
		}

		// 2) Keep the top of the screen covered: as soon as the topmost lane
		//    leaves a gap above it, bring a new/recycled lane in on top.
		while (lanes.front()->getPosition().y > 0.f)
			spawnLane(lanes, lanes.front()->getPosition().y - Constants::LANE_HEIGHT);

		// ── Render ─────────────────────────────────────────────────────────
		window.clear({20, 22, 28});
		for (Lane* lane : lanes)
			lane->render(window);
		drawSidebar(window);
		window.display();
	}

	for (Lane* lane : lanes)
		delete lane;

	return 0;
}
